def resolve(path, cwd, links):
    def split_path(p):
        """Split a path into components, filtering empty ones and '.'"""
        parts = p.split('/')
        return [part for part in parts if part and part != '.']

    def resolve_component(current, component, links, link_count):
        """Resolve a single component from current path"""
        if component == '..':
            # Move to parent
            if current == '/':
                return '/', link_count
            return current.rsplit('/', 1)[0] or '/', link_count
        else:
            # Append component
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if it's a symlink
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None, None

                target = links[candidate]
                # Resolve the target relative to the symlink's directory
                if target.startswith('/'):
                    base = '/'
                    target_components = split_path(target)
                else:
                    # Target is relative to the directory containing the symlink
                    if candidate == '/':
                        base = '/'
                    else:
                        base = candidate.rsplit('/', 1)[0] or '/'
                    target_components = split_path(target)

                # Resolve target components from base
                current = base
                for comp in target_components:
                    current, link_count = resolve_component(current, comp, links, link_count)
                    if current is None:
                        return None, None

                return current, link_count

            return candidate, link_count

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = split_path(path)
    else:
        current = cwd
        components = split_path(path)

    link_count = 0

    # Process each component
    for component in components:
        current, link_count = resolve_component(current, component, links, link_count)
        if current is None:
            return None

    # Return the canonical path without trailing slash (except for root)
    if current == '/':
        return '/'
    return current

